function onSubmit() {
   //Type appropriate comment here, and begin script below

	var ga = new GlideAjax('x_hccc_hoc_ohs.HoCOHSMPdfReprocessorAjax');
	ga.addParam('sysparm_name', 'reprocessPDF');
	ga.addParam('sysparm_case_sys_id', g_form.getValue('ohsm_case'));
	ga.addParam('sysparm_case_pdf_template', g_form.getValue('pdf_template'));
	ga.addParam('sysparm_case_file_name', g_form.getValue('file_name'));
	g_form.addInfoMessage("Submitting request");
	ga.getXML(function() {
		//var answer = JSON.parse(response.responseXML.documentElement.getAttribute("answer"));
		g_form.addInfoMessage("Submission has been done");
	});



   return false;
}
